class Solution {
    private boolean valid(int[][] grid, int row, boolean flip) {
        int n = grid[0].length;
        for (int j = 0; j < n; j++) {
            int val = flip ? 1 - grid[0][j] : grid[0][j];
            if (grid[row][j] != val) return false;
        }
        return true;
    }

    public boolean removeOnes(int[][] grid) {
        for (int i = 1; i < grid.length; i++)
            if (!(valid(grid, i, true) || valid(grid, i, false))) return false;
        return true;
    }
}
